import threading
from typing import Callable, Any, Dict

class BulkheadFullError(Exception):
    """Raised when a tenant's bulkhead has no capacity left (both active and queue are full)."""
    pass

class TenantBulkhead:
    """Per‑tenant bulkhead implementation.

    Guarantees that each tenant can have at most ``max_concurrent`` functions executing
    concurrently and at most ``max_queue_size`` callers waiting for a slot. Callers that
    exceed these limits receive a :class:`BulkheadFullError` without affecting other tenants.
    """

    def __init__(self, max_concurrent: int = 2, max_queue_size: int = 2):
        # ----- validation of construction parameters -----
        if type(max_concurrent) is not int:
            raise TypeError("max_concurrent must be an int")
        if max_concurrent <= 0:
            raise ValueError("max_concurrent must be a positive integer")
        if type(max_queue_size) is not int:
            raise TypeError("max_queue_size must be an int")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be a non‑negative integer")

        self.max_concurrent = max_concurrent
        self.max_queue_size = max_queue_size
        self._lock = threading.Lock()
        # tenant_id -> {'active': int, 'queue': int, 'cond': threading.Condition}
        self._tenants: Dict[str, Dict[str, Any]] = {}

    # ---------------------------------------------------------------------
    # Internal helpers
    # ---------------------------------------------------------------------
    def _validate_tenant_id(self, tenant_id: Any) -> str:
        if not isinstance(tenant_id, str) or tenant_id == "":
            raise ValueError("tenant_id must be a non‑empty string")
        return tenant_id

    def _validate_callable(self, func: Any) -> Callable:
        if not callable(func) or isinstance(func, bool):
            raise ValueError("func must be a callable and not a boolean")
        return func  # type: ignore[return-value]

    def _get_or_create_tenant(self, tenant_id: str) -> Dict[str, Any]:
        """Return the per‑tenant state dictionary, creating it if necessary.

        The returned dict contains keys ``active``, ``queue`` and ``cond``.
        """
        with self._lock:
            if tenant_id not in self._tenants:
                self._tenants[tenant_id] = {
                    "active": 0,
                    "queue": 0,
                    "cond": threading.Condition(self._lock),
                }
            return self._tenants[tenant_id]

    # ---------------------------------------------------------------------
    # Public API
    # ---------------------------------------------------------------------
    def execute(self, tenant_id: Any, func: Any, *args, **kwargs) -> Any:
        """Execute ``func`` under the bulkhead constraints for ``tenant_id``.

        The call is *synchronous*: the caller blocks until a concurrency slot is
        available or the bulkhead is full. If the bulkhead for the tenant is full
        (active >= ``max_concurrent`` **and** queued callers >= ``max_queue_size``),
        a :class:`BulkheadFullError` is raised immediately.
        """
        # ----- entry‑point validation -----
        tenant_id = self._validate_tenant_id(tenant_id)
        func = self._validate_callable(func)

        tenant = self._get_or_create_tenant(tenant_id)
        cond: threading.Condition = tenant["cond"]

        # ----- acquire a slot or raise -----
        with cond:
            if tenant["active"] < self.max_concurrent:
                tenant["active"] += 1
            else:
                if tenant["queue"] >= self.max_queue_size:
                    raise BulkheadFullError(
                        f"Bulkhead capacity reached for tenant '{tenant_id}'"
                    )
                tenant["queue"] += 1
                # Wait until a running slot becomes free.
                while tenant["active"] >= self.max_concurrent:
                    cond.wait()
                tenant["queue"] -= 1
                tenant["active"] += 1

        # ----- execute the user function -----
        try:
            return func(*args, **kwargs)
        finally:
            # ----- release the slot and notify waiting callers -----
            with cond:
                if tenant["active"] > 0:
                    tenant["active"] -= 1
                # Wake one waiting thread, if any.
                cond.notify()
                # Clean up empty tenant entries to avoid unbounded growth.
                if tenant["active"] == 0 and tenant["queue"] == 0:
                    # Safe removal under the same lock.
                    del self._tenants[tenant_id]

import threading

class BulkheadFullError(Exception):
    pass

class TenantBulkhead:
    def __init__(self, max_concurrent=2, max_queue_size=2):
        # Validate configuration parameters
        if isinstance(max_concurrent, bool) or not isinstance(max_concurrent, int):
            raise TypeError("max_concurrent must be an integer")
        if max_concurrent <= 0:
            raise ValueError("max_concurrent must be a positive integer")
        if isinstance(max_queue_size, bool) or not isinstance(max_queue_size, int):
            raise TypeError("max_queue_size must be an integer")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be a non‑negative integer")

        self.max_concurrent = max_concurrent
        self.max_queue_size = max_queue_size
        self.lock = threading.Lock()
        # Per‑tenant state
        self._active_counts = {}   # tenant_id -> currently running tasks
        self._queue_counts = {}    # tenant_id -> queued but waiting tasks
        self._conditions = {}      # tenant_id -> threading.Condition for waiting

    def _get_condition(self, tenant_id):
        """Retrieve or create a Condition object for a given tenant."""
        if tenant_id not in self._conditions:
            self._conditions[tenant_id] = threading.Condition(self.lock)
        return self._conditions[tenant_id]

    def execute(self, tenant_id, func, *args, **kwargs):
        # ---- Input validation ----
        if isinstance(tenant_id, bool) or not isinstance(tenant_id, str) or tenant_id == "":
            raise ValueError("tenant_id must be a non‑empty string")
        if not callable(func):
            raise ValueError("func must be callable")
        # No need to validate *args/**kwargs here; they are passed through.

        # ---- Acquire slot or queue ----
        with self.lock:
            # Initialize counters for this tenant if absent
            active = self._active_counts.get(tenant_id, 0)
            queue = self._queue_counts.get(tenant_id, 0)
            cond = self._get_condition(tenant_id)

            if active < self.max_concurrent:
                # Immediate execution slot available
                self._active_counts[tenant_id] = active + 1
                queued = False
            else:
                # No immediate slot; enforce queue capacity
                if queue >= self.max_queue_size:
                    raise BulkheadFullError("Bulkhead capacity reached for tenant '{}'".format(tenant_id))
                # Increment queue count and wait for a slot
                self._queue_counts[tenant_id] = queue + 1
                queued = True
                while self._active_counts.get(tenant_id, 0) >= self.max_concurrent:
                    cond.wait()
                # Slot became available; adjust counters
                self._queue_counts[tenant_id] -= 1
                self._active_counts[tenant_id] = self._active_counts.get(tenant_id, 0) + 1

        try:
            return func(*args, **kwargs)
        finally:
            # ---- Release slot and notify waiting tenants ----
            with self.lock:
                # Decrement active count safely
                current_active = self._active_counts.get(tenant_id, 0)
                if current_active <= 0:
                    # Defensive: should never happen, but guard against underflow
                    self._active_counts[tenant_id] = 0
                else:
                    self._active_counts[tenant_id] = current_active - 1
                # Notify any waiting threads for this tenant
                cond = self._conditions.get(tenant_id)
                if cond:
                    cond.notify_all()
                # Clean up empty entries to avoid unbounded growth
                if self._active_counts.get(tenant_id) == 0:
                    self._active_counts.pop(tenant_id, None)
                if self._queue_counts.get(tenant_id) == 0:
                    self._queue_counts.pop(tenant_id, None)
                # Remove condition if no pending work for tenant
                if (tenant_id not in self._active_counts) and (tenant_id not in self._queue_counts):
                    self._conditions.pop(tenant_id, None)
